# Adapter Pattern

The Adapter pattern lets you make incompatible interfaces work together. It wraps an object with an incompatible interface into an adapter that the client code expects.

**When to use:** You have existing code (or a third-party library) with one interface, but your system expects a different one. You don't want to (or can't) modify the original code.

## Practical Example

Say you have a system that processes payments. Your code expects a unified `PaymentProcessor` interface, but you need to integrate two different third-party payment SDKs with completely different APIs.

```python
from dataclasses import dataclass


# --- Your system's expected interface ---

class PaymentProcessor:
    """Interface your system works with."""

    def pay(self, amount: float, currency: str) -> dict:
        raise NotImplementedError


# --- Third-party SDKs you can't modify ---

class StripeSDK:
    """Stripe-like SDK with its own API shape."""

    def create_charge(self, amount_cents: int, cur: str, idempotency_key: str) -> dict:
        # Imagine this hits a real API
        return {"id": "ch_abc123", "status": "succeeded", "amount": amount_cents}


class PayPalSDK:
    """PayPal-like SDK with a completely different API."""

    def send_payment(self, value: str, currency_code: str) -> dict:
        # Imagine this hits a real API
        return {"payment_id": "PAY-xyz", "state": "approved"}


# --- Adapters ---

class StripeAdapter(PaymentProcessor):
    def __init__(self, sdk: StripeSDK):
        self._sdk = sdk

    def pay(self, amount: float, currency: str) -> dict:
        amount_cents = int(amount * 100)
        result = self._sdk.create_charge(amount_cents, currency, idempotency_key="key123")
        return {"success": result["status"] == "succeeded", "transaction_id": result["id"]}


class PayPalAdapter(PaymentProcessor):
    def __init__(self, sdk: PayPalSDK):
        self._sdk = sdk

    def pay(self, amount: float, currency: str) -> dict:
        result = self._sdk.send_payment(value=f"{amount:.2f}", currency_code=currency)
        return {"success": result["state"] == "approved", "transaction_id": result["payment_id"]}


# --- Client code doesn't care which provider is behind the adapter ---

def checkout(processor: PaymentProcessor, amount: float, currency: str):
    result = processor.pay(amount, currency)
    if result["success"]:
        print(f"Payment {result['transaction_id']} completed.")
    else:
        print("Payment failed.")


# Usage
stripe_processor = StripeAdapter(StripeSDK())
paypal_processor = PayPalAdapter(PayPalSDK())

checkout(stripe_processor, 29.99, "USD")
checkout(paypal_processor, 29.99, "USD")
```

## Why this works well

| Without Adapter | With Adapter |
|---|---|
| Client code has `if/elif` branches for each SDK | Client code calls one uniform `.pay()` method |
| Adding a new provider means touching client logic | Adding a new provider = one new adapter class |
| Hard to test (coupled to SDK details) | Easy to mock `PaymentProcessor` in tests |

## Key points

- The adapter holds a reference to the adaptee (the incompatible object) and translates calls.
- The client depends only on the target interface, never on the concrete SDK.
- It's the same idea as a physical power adapter — you don't rewire the device, you put a converter in between.

```typescript
import { EventEmitter } from "events";

interface PoolOptions {
  minSize: number;
  maxSize: number;
  acquireTimeoutMs: number;
  idleTimeoutMs: number;
  maxLifetimeMs: number;
  validateOnAcquire: boolean;
}

interface PooledConnection<T> {
  resource: T;
  createdAt: number;
  lastUsedAt: number;
  id: number;
}

interface PendingRequest<T> {
  resolve: (conn: T) => void;
  reject: (err: Error) => void;
  timer: ReturnType<typeof setTimeout>;
}

type ConnectionFactory<T> = {
  create: () => Promise<T>;
  destroy: (resource: T) => Promise<void>;
  validate: (resource: T) => Promise<boolean>;
};

class ConnectionPool<T> extends EventEmitter {
  private options: PoolOptions;
  private factory: ConnectionFactory<T>;
  private idle: PooledConnection<T>[] = [];
  private active: Set<PooledConnection<T>> = new Set();
  private pendingRequests: PendingRequest<T>[] = [];
  private connectionId = 0;
  private closed = false;
  private idleCheckInterval: ReturnType<typeof setInterval> | null = null;

  constructor(factory: ConnectionFactory<T>, options: Partial<PoolOptions> = {}) {
    super();
    this.factory = factory;
    this.options = {
      minSize: options.minSize ?? 2,
      maxSize: options.maxSize ?? 10,
      acquireTimeoutMs: options.acquireTimeoutMs ?? 5000,
      idleTimeoutMs: options.idleTimeoutMs ?? 30000,
      maxLifetimeMs: options.maxLifetimeMs ?? 300000,
      validateOnAcquire: options.validateOnAcquire ?? true,
    };

    if (this.options.minSize < 0) throw new Error("minSize must be >= 0");
    if (this.options.maxSize < 1) throw new Error("maxSize must be >= 1");
    if (this.options.minSize > this.options.maxSize) {
      throw new Error("minSize cannot exceed maxSize");
    }

    this.startIdleCheck();
  }

  get size(): number {
    return this.idle.length + this.active.size;
  }

  get availableCount(): number {
    return this.idle.length;
  }

  get pendingCount(): number {
    return this.pendingRequests.length;
  }

  async initialize(): Promise<void> {
    const promises: Promise<void>[] = [];
    for (let i = 0; i < this.options.minSize; i++) {
      promises.push(this.addConnection());
    }
    await Promise.all(promises);
  }

  async acquire(): Promise<T> {
    if (this.closed) {
      throw new Error("Pool is closed");
    }

    // Try to get an idle connection
    while (this.idle.length > 0) {
      const conn = this.idle.pop()!;

      if (this.isExpired(conn)) {
        await this.destroyConnection(conn);
        continue;
      }

      if (this.options.validateOnAcquire) {
        try {
          const valid = await this.factory.validate(conn.resource);
          if (!valid) {
            await this.destroyConnection(conn);
            continue;
          }
        } catch {
          await this.destroyConnection(conn);
          continue;
        }
      }

      conn.lastUsedAt = Date.now();
      this.active.add(conn);
      this.emit("acquire", conn.id);
      return conn.resource;
    }

    // No idle connections — create one if under max
    if (this.size < this.options.maxSize) {
      const conn = await this.createConnection();
      conn.lastUsedAt = Date.now();
      this.active.add(conn);
      this.emit("acquire", conn.id);
      return conn.resource;
    }

    // At capacity — wait in queue
    return new Promise<T>((resolve, reject) => {
      const timer = setTimeout(() => {
        const idx = this.pendingRequests.findIndex((r) => r.timer === timer);
        if (idx !== -1) {
          this.pendingRequests.splice(idx, 1);
        }
        reject(new Error(`Acquire timeout after ${this.options.acquireTimeoutMs}ms`));
      }, this.options.acquireTimeoutMs);

      this.pendingRequests.push({ resolve, reject, timer });
    });
  }

  async release(resource: T): Promise<void> {
    if (this.closed) {
      // Pool closed while resource was checked out — just destroy
      try {
        await this.factory.destroy(resource);
      } catch {
        // swallow
      }
      return;
    }

    const conn = this.findActive(resource);
    if (!conn) {
      // Double release or unknown resource — ignore silently
      return;
    }

    this.active.delete(conn);
    conn.lastUsedAt = Date.now();

    if (this.isExpired(conn)) {
      await this.destroyConnection(conn);
      this.ensureMinSize();
      return;
    }

    // Serve a pending request first
    if (this.pendingRequests.length > 0) {
      const pending = this.pendingRequests.shift()!;
      clearTimeout(pending.timer);
      conn.lastUsedAt = Date.now();
      this.active.add(conn);
      this.emit("acquire", conn.id);
      pending.resolve(conn.resource);
      return;
    }

    // Return to idle pool
    this.idle.push(conn);
    this.emit("release", conn.id);
  }

  async destroy(resource: T): Promise<void> {
    const conn = this.findActive(resource);
    if (conn) {
      this.active.delete(conn);
      await this.destroyConnection(conn);
      this.ensureMinSize();
    }
  }

  async drain(): Promise<void> {
    this.closed = true;

    if (this.idleCheckInterval) {
      clearInterval(this.idleCheckInterval);
      this.idleCheckInterval = null;
    }

    // Reject all pending requests
    for (const pending of this.pendingRequests) {
      clearTimeout(pending.timer);
      pending.reject(new Error("Pool is draining"));
    }
    this.pendingRequests = [];

    // Destroy all idle connections
    const destroyPromises = this.idle.map((conn) => this.destroyConnection(conn));
    this.idle = [];
    await Promise.all(destroyPromises);

    // Wait for active connections to be released (with a hard timeout)
    if (this.active.size > 0) {
      await Promise.race([
        new Promise<void>((resolve) => {
          const check = setInterval(() => {
            if (this.active.size === 0) {
              clearInterval(check);
              resolve();
            }
          }, 100);
        }),
        new Promise<void>((resolve) => setTimeout(resolve, 10000)),
      ]);

      // Force-destroy any remaining
      const remaining = [...this.active];
      this.active.clear();
      await Promise.all(remaining.map((conn) => this.destroyConnection(conn)));
    }

    this.emit("drain");
  }

  private async createConnection(): Promise<PooledConnection<T>> {
    const resource = await this.factory.create();
    const conn: PooledConnection<T> = {
      resource,
      createdAt: Date.now(),
      lastUsedAt: Date.now(),
      id: ++this.connectionId,
    };
    this.emit("create", conn.id);
    return conn;
  }

  private async destroyConnection(conn: PooledConnection<T>): Promise<void> {
    try {
      await this.factory.destroy(conn.resource);
    } catch (err) {
      this.emit("error", err);
    }
    this.emit("destroy", conn.id);
  }

  private async addConnection(): Promise<void> {
    try {
      const conn = await this.createConnection();
      this.idle.push(conn);
    } catch (err) {
      this.emit("error", err);
    }
  }

  private findActive(resource: T): PooledConnection<T> | undefined {
    for (const conn of this.active) {
      if (conn.resource === resource) return conn;
    }
    return undefined;
  }

  private isExpired(conn: PooledConnection<T>): boolean {
    const now = Date.now();
    return now - conn.createdAt > this.options.maxLifetimeMs;
  }

  private startIdleCheck(): void {
    this.idleCheckInterval = setInterval(async () => {
      if (this.closed) return;

      const now = Date.now();
      const toRemove: PooledConnection<T>[] = [];

      this.idle = this.idle.filter((conn) => {
        const idle = now - conn.lastUsedAt > this.options.idleTimeoutMs;
        const expired = this.isExpired(conn);
        const surplus = this.size > this.options.minSize;

        if ((idle || expired) && surplus) {
          toRemove.push(conn);
          return false;
        }
        return true;
      });

      for (const conn of toRemove) {
        await this.destroyConnection(conn);
      }

      this.ensureMinSize();
    }, Math.min(this.options.idleTimeoutMs / 2, 5000));
  }

  private ensureMinSize(): void {
    if (this.closed) return;
    const deficit = this.options.minSize - this.size;
    for (let i = 0; i < deficit; i++) {
      this.addConnection();
    }
  }
}

export { ConnectionPool, ConnectionFactory, PoolOptions };
```

Key design decisions and edge cases handled:

- **Acquire timeout** — callers don't hang forever when pool is exhausted. Queued requests get rejected after the configured timeout.
- **Connection validation** — stale/broken connections are detected on acquire and silently replaced.
- **Max lifetime eviction** — prevents connections from living forever (important for DB failovers, DNS changes, etc.).
- **Idle timeout with minimum guarantee** — idle connections get reaped, but the pool never shrinks below `minSize`.
- **Double release** — silently ignored instead of corrupting state.
- **Release after drain** — resource gets destroyed instead of returned to a dead pool.
- **Graceful drain** — rejects pending waiters, destroys idle connections, waits (with hard timeout) for active ones, then force-destroys stragglers.
- **Factory errors** — creation/destruction failures are caught and emitted rather than crashing the pool.
- **FIFO queue fairness** — pending requests are served in order when connections become available.

Usage would look like:

```typescript
const pool = new ConnectionPool({
  create: () => connectToDb(),
  destroy: (conn) => conn.close(),
  validate: (conn) => conn.ping(),
}, { maxSize: 20, acquireTimeoutMs: 3000 });

await pool.initialize();

const conn = await pool.acquire();
try {
  await conn.query("SELECT 1");
} finally {
  await pool.release(conn);
}
```

Here's a test suite for an email validation function. I'll write it in Python with `pytest` since you didn't specify a language — easy to adapt.

First, the assumed interface:

```python
def validate_email(email: str) -> bool:
